// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager, IERC20, IGlpManager, IRewardRouterV2, SafeCast} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    MockERC20 sGlp;
    MockERC20 usdc;
    MockGlpManager glpManager;
    MockRouter router;
    address juniorVault = address(0xA11CE);

    function setUp() public {
        c = new DnGmxBatchingManager();
        sGlp = new MockERC20();
        usdc = new MockERC20();
        glpManager = new MockGlpManager();
        router = new MockRouter();
        c.initialize(
            IERC20(address(sGlp)),
            IERC20(address(usdc)),
            IRewardRouterV2(address(router)),
            IGlpManager(address(glpManager)),
            juniorVault,
            address(this)
        );
    }

    function testFuzz_property(uint256 glpAmount) public {
        glpAmount = bound(glpAmount, 1, 1e30); // positive tracked balance, SafeCast-safe

        // vault stakes GLP on behalf of the junior vault via depositToken
        router.setOut(glpAmount);
        vm.prank(juniorVault);
        c.depositToken(address(sGlp), 100, 0);

        // pass cooldown and run the keeper batch deposit
        vm.warp(3601);
        c.executeBatchDeposit();

        // The tracked balance must be reset to zero after transferring it out.
        assertTrue(c.dnGmxJuniorVaultGlpBalance() == 0, "tracked GLP balance must be reset after batch deposit");
    }
}

contract MockERC20 {
    function transferFrom(address, address, uint256) external returns (bool) { return true; }
    function transfer(address, uint256) external returns (bool) { return true; }
    function approve(address, uint256) external returns (bool) { return true; }
}

contract MockGlpManager {
    function vault() external view returns (address) { return address(1); }
}

contract MockRouter {
    uint256 public out;
    function setOut(uint256 x) external { out = x; }
    function mintAndStakeGlp(address, uint256, uint256, uint256) external view returns (uint256) { return out; }
}
